// AuthController login method
public function login(Request $request) {
    $credentials = $request->validate([...]);

    if (!Auth::attempt($credentials)) {
        throw new AuthenticationException();
    }

    $user = Auth::user();
    $accessToken = $user->createToken('access', ['*'], now()->addMinutes(15));
    $refreshToken = $this->tokenService->createRefreshToken($user);

    return response()->json(['user' => $user, 'roles' => $user->roles])
        ->withCookie(cookie('access_token', $accessToken->plainTextToken, 15, '/', null, true, true, false, 'Strict'))
        ->withCookie(cookie('refresh_token', $refreshToken, 10080, '/', null, true, true, false, 'Strict'))
        ->withCookie(cookie('user_role', $user->primaryRole(), null, '/', null, false, false, false, 'Strict'));
}
